package com.example.hiringsys.service; import com.example.hiringsys.entity.Cargo; import com.example.hiringsys.exception.*; import com.example.hiringsys.repository.CargoRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.List;
@Service public class CargoService {private final CargoRepository repository;public CargoService(CargoRepository r){repository=r;}@Transactional(readOnly=true)public List<Cargo> listarTodos(){return repository.findAll();}@Transactional(readOnly=true)public Cargo buscarPorId(Long id){return repository.findById(id).orElseThrow(()->new ResourceNotFoundException("Cargo não encontrado: "+id));}@Transactional(readOnly=true)public List<Cargo> buscarPorNome(String nome){return repository.findByNomeContainingIgnoreCase(nome);}@Deprecated @Transactional(readOnly=true)public List<Cargo> buscarPorDepartamento(Long id){return List.of();}@Transactional public Cargo salvar(Cargo c){c.setId(null);validar(c.getNome(),null);return repository.save(c);}@Transactional public Cargo atualizar(Long id,Cargo d){Cargo c=buscarPorId(id);validar(d.getNome(),id);c.setNome(d.getNome());return repository.save(c);}@Transactional public void excluir(Long id){repository.delete(buscarPorId(id));}private void validar(String n,Long id){boolean x=id==null?repository.existsByNomeIgnoreCase(n):repository.existsByNomeIgnoreCaseAndIdNot(n,id);if(x)throw new BusinessRuleException("Cargo já cadastrado: "+n);}}
